SELECT ST_XMin(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS xmin, ST_YMin(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS ymin, ST_ZMin(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS zmin, ST_XMax(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS xmax, ST_YMax(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS ymax, ST_ZMax(ST_Expand(ST_3DMakeBox(ST_PointZ(1, 2, 3), ST_PointZ(4, 5, 6)), $1, $2, $3)) AS zmax
